contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to exercise public functions: whaleAddr and wagerLimit were set when C was deployed by the checker.
    // We need to open the contract to the public (onlyOwner) — the test contract is the owner because checker deploys C with this contract as msg.sender.
    // run accepts an amount to send with wager and a dummy address (unused) to vary inputs.
    function run(uint256 amount, address dummy) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // Preconditions: open contract to public so wager/play/donate can be called
        c.OpenToThePublic();

        // Read current bet limit and difficulty
        uint256 bl = c.currentBetLimit();
        uint256 diff = c.currentDifficulty();

        // We only attempt to wager when amount equals bet limit to satisfy wager's require
        bool willPayExact = (amount == bl);

        // Call wager if we are sending exact betLimit; otherwise skip it (still allowed by property)
        bool wagerReverted;
        if (willPayExact) {
            // Ensure we have balance to send
            try c.wager{value: amount}() {
                wagerReverted = false;
            } catch {
                wagerReverted = true;
            }
        } else {
            wagerReverted = true; // treat as no successful wager
        }

        // Observe hasPlayerWagered (msg.sender is this contract)
        bool hasWagered = c.hasPlayerWagered(address(this));

        // Observe winnersPot and contract balance
        uint256 pot = c.winnersPot();
        uint256 cbalance = address(c).balance;

        // General rule asserted:
        // If the wager call was made with exact betLimit and did not revert, then hasPlayerWagered must be true.
        // Additionally, winnersPot() must be <= contract balance (sanity for pot computation) and pot equals cbalance/2.
        // We combine these into one general assert over observables and inputs.
        assert((!willPayExact || wagerReverted || hasWagered) && (pot == cbalance / 2));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function doing all work
    function run(uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance");

        // open contract to public (this contract is owner because checker deployed C with this as msg.sender)
        c.OpenToThePublic();

        // read current bet limit (view)
        uint256 bl = c.currentBetLimit();

        // attempt to call wager{value: sendAmount}() as a top-level state-changing call
        bool wagerReverted;
        try c.wager{value: sendAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // observe whether this contract is recorded as having wagered
        bool hasWagered = c.hasPlayerWagered(address(this));

        // observe pot and contract balance
        uint256 pot = c.winnersPot();
        uint256 cbalance = address(c).balance;

        // General rule:
        // If we called wager with exactly the current bet limit and it did not revert,
        // then the contract must record that this address has wagered, and winnersPot() must equal half of the contract balance.
        assert(((sendAmount != bl) || wagerReverted || hasWagered) && (pot == cbalance / 2));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function doing all work
    // We take amount to send when calling donate
    function run(uint256 amount) public payable {
        // ensure this test contract has enough balance to forward 'amount'
        require(address(this).balance >= amount);

        // make contract open to public so donate can be called (this contract is owner because checker deployed C with this as msg.sender)
        c.OpenToThePublic();

        // record contract balance before
        uint256 before = address(c).balance;

        // attempt to call donate{value: amount}()
        bool reverted;
        try c.donate{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record balance after
        uint256 after = address(c).balance;

        // General rule:
        // If the donate call did not revert, then the contract balance must have increased by exactly amount.
        // If it reverted, then the balance must be unchanged.
        // (This captures that donate either forwards the Ether to the whale via donateToWhale or reverts; in both cases the contract's visible balance changes accordingly.)
        assert((!reverted && after == before + amount) || (reverted && after == before));
    }

    // Allow receiving Ether so this test can forward funds
    receive() external payable { }
}

