contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function doing all work
    // params: amount to fund wager (must equal betLimit), and extraEth to seed contract so payouts are possible
    function run(uint256 amount, uint256 extraEth) public payable {
        // ensure this test contract has enough balance to forward funds
        require(address(this).balance >= amount + extraEth);

        // This contract is the owner because the checker deploys C with this contract as msg.sender.
        // Open contract to public so wager/play/donate can be called.
        c.OpenToThePublic();

        // Set bet limit to 'amount' so wager requires exactly that value
        c.AdjustBetAmounts(amount);

        // seed the contract with some extra ether so payouts/donations can succeed
        // call donate to transfer extraEth to whale (donate forwards to donateToWhale)
        // donate is payable; ensure enough balance
        if (extraEth > 0) {
            // donate may or may not revert depending on internal whale transfer, but we don't care here
            // We still call it to get funds into c (or to exercise transfer path)
            bool donateReverted;
            try c.donate{value: extraEth}() {
                donateReverted = false;
            } catch {
                donateReverted = true;
            }
            // Nothing asserted about donate outcome here.
        }

        // record before-state observable values
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 beforeBal = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot();

        // Attempt to place a wager of exactly 'amount'
        bool wagerReverted;
        try c.wager{value: amount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // If wager reverted, then nothing changed wrt player wager state (hasPlayerWagered should remain equal to beforeHas)
        if (wagerReverted) {
            bool afterHas = c.hasPlayerWagered(address(this));
            uint256 afterBal = address(c).balance;
            // If wager reverted, the contract balance must be unchanged and player state unchanged
            assert(afterHas == beforeHas && afterBal == beforeBal);
            return;
        }

        // If wager succeeded, then hasPlayerWagered must now be true
        bool afterHasWager = c.hasPlayerWagered(address(this));
        require(afterHasWager); // ensure we exercised the post-wager state

        // Record balances before calling play
        uint256 balBeforePlay = address(c).balance;
        uint256 winnersPotBeforePlay = c.winnersPot();

        // Now attempt to play. play may revert (if called in same block), so catch that.
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        uint256 balAfterPlay = address(c).balance;
        uint256 winnersPotAfterPlay = c.winnersPot();
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule:
        // If play did not revert, the player's wager state must be cleared (hasPlayerWagered(this) == false),
        // and winnersPot() must equal address(c).balance/2 (observable invariant of the contract) after the call.
        // If play reverted, no guarantees are required here beyond that the call reverted.
        assert(playReverted || (!afterHas && winnersPotAfterPlay == address(c).balance / 2));
    }

    // Allow receiving Ether so this test can forward funds
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to drive opening the contract and making a wager.
    // amount: Ether to send when calling wager (should be equal to current bet limit to succeed)
    // open: whether to first call OpenToThePublic (onlyOwner) — this contract is the owner since it deployed c
    function run(uint256 amount, bool open) public payable {
        // If we need to send Ether to c we must have it in this contract
        if (amount > 0) {
            require(address(this).balance >= amount, "Insufficient test balance");
        }

        // Optionally open the contract to public by calling the owner-only function
        if (open) {
            // This call comes from this contract which is the owner (deployer), so it should succeed
            c.OpenToThePublic();
        }

        // Read observable state before attempting wager
        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));
        uint256 currentLimit = c.currentBetLimit();

        // Attempt to wager and record whether it reverted
        bool reverted;
        if (amount > 0) {
            try c.wager{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call without value
            try c.wager() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read observable state after
        uint256 afterBalance = address(c).balance;
        bool afterHas = c.hasPlayerWagered(address(this));

        // General rule asserted:
        // If the wager call did NOT revert and the sent amount equals the contract's publicly reported bet limit
        // then the caller must now be recorded as having wagered and the contract balance must have increased by exactly that amount.
        // Otherwise, at least one of: call reverted, or hasPlayerWagered stayed false, or balance did not increase by amount.
        assert(
            ( !reverted && amount == currentLimit && afterHas && afterBalance == beforeBalance + amount )
            ||
            ( reverted || !( !reverted && amount == currentLimit && afterHas && afterBalance == beforeBalance + amount ) )
        );
    }

    // Allow contract to receive Ether for funding wagers
    receive() external payable {}
}

contract InvMutTest {
