contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to wager exactly the current bet limit and then call play; assert invariant about outcomes.
    // We take depositAmount as a parameter and require the test contract has that Ether.
    function run(uint256 depositAmount) public payable {
        // Ensure this test contract has enough Ether to send the deposit
        require(address(this).balance >= depositAmount, "not enough ether");

        // Read current bet limit from c
        uint256 currentLimit = c.currentBetLimit();

        // We only test the meaningful case: deposit must match bet limit
        require(currentLimit > 0, "bet limit must be positive");
        require(depositAmount == currentLimit, "deposit must equal current bet limit");

        // Record contract balance before any state-changing calls
        uint256 balBeforeAny = address(c).balance;

        // Attempt to wager with the required amount; capture whether it reverted
        bool wagerReverted;
        try c.wager{value: depositAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }

        // Observe whether c thinks this contract has an active wager
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // Record balance before trying to play
        uint256 balBeforePlay = address(c).balance;

        // Attempt to call play; it may revert (e.g., same block, not open to public, or not a player)
        bool playReverted;
        try c.play() {
            playReverted = false;
        } catch {
            playReverted = true;
        }

        // Balance after attempting play
        uint256 balAfterPlay = address(c).balance;

        // Observe wager state after play attempt
        bool hasWagerFinal = c.hasPlayerWagered(address(this));

        // Assert the general rule:
        // - If wager reverted: no wager recorded and no change to contract balance.
        // - If wager succeeded: either play reverted and wager state unchanged and balance unchanged,
        //   or play succeeded and wager cleared and contract balance did not increase compared to before play.
        assert(
            (wagerReverted && hasWagerAfter == false && balBeforeAny == balAfterPlay)
            ||
            (!wagerReverted && playReverted && hasWagerAfter == hasWagerFinal && balBeforePlay == balAfterPlay)
            ||
            (!wagerReverted && !playReverted && hasWagerFinal == false && balAfterPlay <= balBeforePlay)
        );
    }

    // Allow receiving ETH so the test harness can fund this contract
    receive() external payable {}
}

