contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // run: open contract to public, set bet limit, then call wager with amount and check effects
    function run(uint256 newBetLimit, uint256 sendAmount) public payable {
        require(address(this).balance >= sendAmount);
        // make this contract the owner by virtue of being the deployer of c per problem statement
        // Adjust bet limit to the provided value (owner-only) and open to public.
        c.AdjustBetAmounts(newBetLimit);
        c.OpenToThePublic();
        // pre-read balance
        uint256 before = address(c).balance;
        bool reverted;
        // attempt to wager sending sendAmount
        try c.wager{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // post-read balance and hasPlayerWagered for this test contract
        uint256 after = address(c).balance;
        bool playerMarked = c.hasPlayerWagered(address(this));
        // If call did not revert, then sendAmount must have equaled the current bet limit (newBetLimit),
        // and the contract balance must have increased by sendAmount, and hasPlayerWagered must be true.
        // If it reverted, then at least one of those implications need not hold; assert the forward implication.
        assert( reverted || (sendAmount == newBetLimit && after == before + sendAmount && playerMarked) );
    }
    receive() external payable {}
}

