    function run(uint256 donateAmount) public payable {
        // we need Ether to forward to c when calling donate
        require(address(this).balance >= donateAmount);
        // as the deployer of c, this contract is owner; enable public access
        c.OpenToThePublic();
        // record before-values
        uint256 beforeBalance = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot();
        bool reverted;
        // perform donate call sending donateAmount wei
        try c.donate{value: donateAmount}() {
