        } catch {
            reverted = true;
        }
        uint256 afterBalance = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot();
        // If donate did not revert, the contract's balance must have decreased by donateAmount and winnersPot must reflect the new half-balance.
        // Expressed as: reverted OR (afterBalance + donateAmount == beforeBalance AND afterWinnersPot * 2 == afterBalance - (afterBalance % 2 == 1 ? 1 : 0) + 0);
        // Simpler, use observable relation: if not reverted then beforeBalance == afterBalance + donateAmount and afterWinnersPot == address(c).balance / 2
        assert(reverted || (beforeBalance == afterBalance + donateAmount && afterWinnersPot == address(c).balance / 2));
    }
