        c.OpenToThePublic();
        // Set bet limit to fundAmount so wager() will require exactly this value
        c.AdjustBetAmounts(fundAmount);

        // Fund the contract so payouts/transfers can occur. Send fundAmount to c via its donate() payable function.
        // This is a state-changing call and must be a top-level statement.
        try c.donate{value: fundAmount}() {
        } catch {
            // ignore if donate reverts; we still proceed — contract might accept direct fallback instead
        }

        // Record observables before wagering/play.
        uint256 beforeBalance = address(c).balance;
        bool beforeHas = c.hasPlayerWagered(address(this));

        // Attempt to place a wager by sending exactly fundAmount. Top-level call.
        bool wagerReverted;
        try c.wager{value: fundAmount}() {
            wagerReverted = false;
