    constructor(C _c) { c = _c; }
    // params: whaleAddress and wagerLimit were used in C constructor at deployment by harness;
    // here we need to open to public, set bet limit, then wager and attempt play after advancing block
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "need funds");
        // ensure contract is open and betLimit equals amount
        // Only owner can call AdjustBetAmounts and OpenToThePublic. The test contract is the owner (it deployed c).
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();

        // place a wager: must send exactly betLimit
        c.wager{value: amount}();

        // read pre-play values
        uint256 beforeBal = address(c).balance;
        bool hadWager = c.hasPlayerWagered(address(this));

        // attempt to play; it may revert if block.number equals timestamp stored (play requires blockNumber < block.number)
        bool reverted;
        try c.play() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-state
        uint256 afterBal = address(c).balance;
        bool hasWagerAfter = c.hasPlayerWagered(address(this));

        // General rule:
        // If play reverted, then nothing asserted about balances here except that the function recognized being called too early.
        // Otherwise, when play succeeded: the player's wager flag must be cleared, and the contract's balance must be at least beforeBal - (amount/2)
        // (play either pays out half the contract balance to winner, or transfers amount/2 to whale via loseWager). So balance cannot drop by more than amount/2.
        assert(
            reverted || (
                hasWagerAfter == false
                && afterBal + (amount/2) >= beforeBal
            )
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // single public entry that performs minimal actions to assert the invariant
    function run(uint256 betAmount) public payable {
        require(address(this).balance >= betAmount, "need funds");
        // make this contract the owner actions: set bet limit and open to public
        c.AdjustBetAmounts(betAmount);
        c.OpenToThePublic();

        // place a wager sending exactly betAmount
        c.wager{value: betAmount}();

        // ensure we did wager according to the public view
        require(c.hasPlayerWagered(address(this)), "wager not recorded");

        // attempt to play; it must not revert for the assertion to be meaningful.
        // If it reverts (e.g., called too early), we don't reach the assert due to try/catch prohibition in contract body here,
        // so we perform the call directly and let it revert the whole run if it fails.
        c.play();

        // After a successful play, the player's wager flag must be cleared.
        assert(c.hasPlayerWagered(address(this)) == false);
    }
    receive() external payable {}
}

